 function stopAudio(){speechEpoch++;if(ownSpeech&&'speechSynthesis'in window)speechSynthesis.cancel();ownSpeech=false;root.querySelectorAll('[data-speaking]').forEach(node=>node.removeAttribute('data-speaking'));}
