 function explorer(){const row=content.letters.find(l=>l.id===letter),host=target().querySelector('#letterExplorer');if(!host)return;
  host.innerHTML='<div class="largeTrainingLetter" role="group" tabindex="-1" aria-label="'+row.id+' maiuscola, '+row.lower+' minuscola">'+row.id+' <small>'+row.lower+'</small></div><div class="trainingAudio"><button class="audio" data-letter-listen="it-IT" data-voice-lang="it-IT">🔊 Nome italiano</button><button class="primary" data-letter-listen="en-GB" data-voice-lang="en-GB">🔊 Nome inglese</button><button class="audio" id="stopLetterAudio">Ferma audio</button></div><p>La stessa lettera scritta può avere un nome diverso nelle due lingue. Ascolta e confronta con un adulto, senza fretta.</p><button class="audio" id="verifyLetterVoice" '+(!voice('en-GB')?'disabled':'')+'>Un adulto ha controllato il nome inglese di '+row.id+'</button><p id="letterVoiceChecked" role="status">'+(verified(row.id)?'Questa lettera è stata controllata con la voce scelta.':'Finché il nome inglese non è controllato, il riconoscimento di questa lettera è una lettura guidata.')+'</p>';
  host.querySelectorAll('[data-letter-listen]').forEach(button=>button.onclick=()=>{const id=voiceId(),lang=button.dataset.letterListen;speakLetter(row.id,lang,()=>{if(lang==='en-GB'){auditioned.add(id+':'+row.id);updateAudioControls();}});});
  host.querySelector('#stopLetterAudio').onclick=stopAudio;host.querySelector('#verifyLetterVoice').onclick=()=>{const id=voiceId();if(!id||!auditioned.has(id+':'+row.id))return;checked[id]=[...new Set([...(Array.isArray(checked[id])?checked[id]:[]),row.id])];try{localStorage.setItem('wordylandLetterVoiceCheck',JSON.stringify(checked));}catch{}explorer();updateAudioControls();host.querySelector('#verifyLetterVoice').focus({preventScroll:true});};updateAudioControls();
 }
 function normalize(value){return String(value??'').toLowerCase().trim().replace(/[.!?,]+$/,'').replace(/\s+/g,' ');}
 function guestPlan(track,block){const plan=[];if(track==='letters'){const pair=content.blocks.find(b=>b.id===block).letters;for(const id of pair){const l=content.letters.find(l=>l.id===id),base={item:'letter:'+id,letter:l,answer:id,choices:pair,topic:'nomi delle lettere'};plan.push({...base,mode:'model'},{...base,choices:Math.random()<.5?[...pair]:[...pair].reverse(),mode:'letter'});}}
  else{const selected=[...content.words].sort((a,b)=>(guest.itemCounts['word:'+a.id]||0)-(guest.itemCounts['word:'+b.id]||0)).slice(0,2);for(const word of selected){const base={item:'word:'+word.id,word,answer:word.id,choices:[word,...content.words.filter(w=>w.id!==word.id).slice(0,2)],topic:word.topic};for(const mode of ['model','recognize','build','recall'])plan.push({...base,mode});}const word=selected[0];plan.push({item:'word:'+word.id,word,answer:word.id,choices:[word,...content.words.filter(w=>w.id!==word.id).slice(0,2)],topic:'piccole frasi',mode:'phrase'});}return plan;
 }
 function validGuest(s){return s&&/^[a-f0-9]{32}$/.test(s.token)&&typeof s.track==='string'&&Array.isArray(s.plan)&&s.plan.length>0&&s.plan.length<=12&&Number.isInteger(s.step)&&s.step>=0&&s.step<=s.plan.length&&Number.isFinite(s.createdAt)&&s.createdAt>=Date.now()-604800000&&s.plan.every(q=>q&&['model','letter','recognize','build','recall','phrase'].includes(q.mode)&&/^(letter:[A-Z]|word:(cat|pen|dog|sun|book|red))$/.test(q.item));}
 function canonicalGuest(s){const next={...s,helped:Boolean(s.helped),hint:Number.isInteger(s.hint)?Math.max(0,Math.min(2,s.hint)):0,errors:Number.isInteger(s.errors)?Math.max(0,Math.min(1000,s.errors)):0};next.plan=s.plan.map(q=>{if(q.item.startsWith('letter:')){const id=q.item.slice(7),l=content.letters.find(l=>l.id===id),pair=content.blocks.find(b=>b.letters.includes(id))?.letters||[id,'A'];return {item:q.item,letter:l,answer:id,choices:pair,mode:q.mode==='model'?'model':'letter',topic:'nomi delle lettere'};}const word=content.words.find(w=>w.id===q.item.slice(5));return {item:q.item,word,answer:word.id,choices:[word,...content.words.filter(w=>w.id!==word.id).slice(0,2)],mode:['model','recognize','build','recall','phrase'].includes(q.mode)?q.mode:'model',topic:word.topic};});next.done=Boolean(s.done)&&next.step===next.plan.length;return next;}
 function saveGuest(next){try{localStorage.setItem(guestKey,JSON.stringify(next));guest=next;}catch{throw Error('Il browser non ha salvato l’allenamento. Libera spazio e riprova: non registriamo un avanzamento non confermato.');}}
 function guestSnapshot(s){return {token:s.token,track:s.track,step:s.step,total:s.plan.length,done:Boolean(s.done),question:s.plan[s.step]||null,helped:Boolean(s.helped),hint:s.hint||0,errors:s.errors||0};}
 async function act(fn){if(busy)return;const current=++operation,generation=epoch,owner=info().id;busy=true;root.setAttribute('aria-busy','true');
  try{const result=await fn(owner);if(current!==operation||generation!==epoch||owner!==info().id||!visible())return;if(result?.session)session=result.session;if(result?.stickers)stickers=result.stickers;return result;}
  catch(error){if(current===operation&&generation===epoch&&visible()){say('Operazione non confermata. '+error.message);const button=document.createElement('button');button.className='audio';button.textContent='Riprendi Allenamento';button.onclick=()=>session?resume(session.token):open();root.querySelector('#trainingStatus').append(button);}}
  finally{if(current===operation){busy=false;root.setAttribute('aria-busy','false');}}
 }
 async function start(track,block='ae'){const result=await act(async owner=>{if(owner)return account.request('training-start',{profile:owner,track,block});const key=track==='letters'?'letters:'+block:'words';let s=guest.sessions.filter(validGuest).find(s=>s.track===key&&!s.done);if(!s){const next=JSON.parse(JSON.stringify(guest));s={token:random(),track:key,plan:guestPlan(track,block),step:0,createdAt:Date.now(),done:false};next.sessions=[...next.sessions.filter(validGuest).slice(-9),s];saveGuest(next);}return {session:guestSnapshot(s),stickers:guest.stickers};});if(result)draw();}
 async function resume(token){const result=await act(async owner=>{if(owner)return account.request('training-state&profile='+owner+'&token='+encodeURIComponent(token));const s=guest.sessions.find(s=>s.token===token&&validGuest(s));if(!s)throw Error('Questo percorso non è più disponibile. Puoi iniziarne uno nuovo.');return {session:guestSnapshot(s),stickers:guest.stickers};});if(result)draw();}
 function showFallback(){const q=session?.question;if(q){const title=root.querySelector('h2');if(title&&['letter','recognize','recall'].includes(q.mode))title.textContent=q.mode==='letter'?'Guarda la lettera e scegli':q.mode==='recognize'?'Leggi la parola e cerca l’immagine':'Guarda e scrivi la parola';}const box=root.querySelector('#trainingFallback');if(box&&session?.question){box.hidden=false;box.textContent=session.question.letter?session.question.letter.id+' '+session.question.letter.lower:session.question.word?.id||'';}const note=root.querySelector('#trainingMode');if(note)note.textContent='Modalità lettura · non è una prova di ascolto';}
 function draw(){stopAudio();helped=Boolean(session.helped);replays=0;audioUsed=false;
  if(session.done){window.wordylandUI?.play();base('Hai fatto un piccolo passo!');target().innerHTML='<p>Ogni tentativo conta. Puoi riposare, ascoltare di nuovo o scoprire un’altra parola.</p>'+stickerMarkup(stickers)+'<button class="primary" id="trainingAgain">Torna ai percorsi</button> <a class="lessonShortcut" href="#allenati">Vai agli esercizi →</a><p>Gli adesivi sono personali. Nessun punto, moneta o confronto con altri bambini.</p>';target().querySelector('button').onclick=open;root.scrollIntoView({block:'start'});root.querySelector('h2').focus({preventScroll:true});return;}
  window.wordylandUI?.play('training');const q=session.question,isLetter=Boolean(q.letter),word=q.word?.id||'',letTitle=q.mode==='model'?(isLetter?'Stessa lettera, due lingue':'Guarda e ascolta la parola'):q.mode==='letter'?'Ascolta il nome inglese':q.mode==='recognize'?'Ascolta e cerca l’immagine':q.mode==='build'?'Componi la parola':q.mode==='phrase'?'Una piccola frase':'Scrivi la parola';
  let title=letTitle;readingFallback=q.mode==='letter'?!(voice('en-GB')&&verified(q.letter.id)):!voice('en-GB');if(q.mode==='recall'&&readingFallback)helped=true;if(readingFallback){if(q.mode==='letter')title='Guarda la lettera e scegli';if(q.mode==='recognize')title='Leggi la parola e cerca l’immagine';if(q.mode==='recall')title='Guarda e scrivi la parola';}base(title);
  target().innerHTML='<div class="trainingSessionTop"><span>'+session.step+' / '+session.total+' attività confermate</span><button class="audio" id="pauseTraining">⏸ Pausa</button></div><p id="trainingMode">'+(readingFallback?'Modalità lettura · non è una prova di ascolto':'Audio della parola intera o del nome della lettera')+'</p><div id="trainingModel"></div><div class="trainingAudio"><button class="primary" id="trainingListen" data-voice-lang="en-GB">🔊 '+(isLetter?'Nome inglese':'Ascolta in inglese')+'</button>'+(isLetter?'<button class="audio" id="trainingItalian" data-voice-lang="it-IT">🔊 Nome italiano · un aiuto</button>':'')+'<button class="audio" id="stopTrainingAudio">Ferma audio</button><button class="audio" id="readTrainingModel">Preferisco leggere</button></div><div id="trainingFallback" class="trainingWord" '+(!readingFallback||q.mode==='model'||q.mode==='build'?'hidden':'')+'>'+esc(isLetter?q.letter.id+' '+q.letter.lower:word)+'</div><div id="trainingExercise"></div><div class="trainingHint"><button class="audio" id="trainingHint">💡 Un aiuto</button><div id="trainingHintModel"></div></div><div id="trainingFeedback" role="status" aria-live="polite"></div>';
  const model=target().querySelector('#trainingModel'),exercise=target().querySelector('#trainingExercise');
  if(q.mode==='model'){model.innerHTML=isLetter?'<div class="largeTrainingLetter">'+q.letter.id+' <small>'+q.letter.lower+'</small></div><p>Confronta il nome italiano e quello inglese con un adulto.</p>':'<div class="trainingImage" aria-hidden="true">'+esc(q.word.emoji)+'</div><div class="trainingWord">'+esc(word)+'</div><p>'+esc(q.word.meaning)+'</p>';exercise.innerHTML='<button class="primary" id="trainingContinue">Continua con calma →</button>';exercise.querySelector('button').onclick=()=>answer(q.answer);}
  else if(q.mode==='letter'){exercise.innerHTML='<div class="trainingChoices twoLetters">'+q.choices.map(id=>'<button class="primary" data-training-choice="'+esc(id)+'">'+esc(id)+' <small>'+esc(id.toLowerCase())+'</small></button>').join('')+'</div>';}
  else if(q.mode==='recognize'){exercise.innerHTML='<div class="trainingChoices">'+q.choices.map(w=>'<button class="audio" data-training-choice="'+esc(w.id)+'" aria-label="'+esc(w.meaning)+'"><span aria-hidden="true">'+esc(w.emoji)+'</span><small>'+esc(w.meaning)+'</small></button>').join('')+'</div>';}
  else if(q.mode==='build'){model.innerHTML='<div class="trainingWord">'+esc(word)+'</div><p>Guarda come si scrive. Tocca le lettere, poi controlla.</p>';build(word,exercise);}
  else if(q.mode==='phrase'){model.innerHTML='<div class="trainingImage" aria-hidden="true">'+esc(q.word.emoji)+'</div><p class="trainingWord">'+esc(q.word.gap)+'</p>';exercise.innerHTML='<div class="trainingChoices">'+q.choices.map(w=>'<button class="audio" data-training-choice="'+esc(w.id)+'">'+esc(w.id)+'</button>').join('')+'</div>';}
  else{model.innerHTML='<div class="trainingImage" aria-hidden="true">'+esc(q.word.emoji)+'</div>';exercise.innerHTML='<form id="trainingWrite"><label for="trainingAnswer">'+(readingFallback?'Copia la parola':'Scrivi senza il modello, se vuoi')+'</label><input id="trainingAnswer" autocomplete="off" autocapitalize="none" spellcheck="false" maxlength="30" required><button class="primary">Controlla</button></form>';exercise.querySelector('form').onsubmit=e=>{e.preventDefault();answer(exercise.querySelector('input').value);};}
  exercise.querySelectorAll('[data-training-choice]').forEach(button=>button.onclick=()=>answer(button.dataset.trainingChoice));
  target().querySelector('#pauseTraining').onclick=open;target().querySelector('#stopTrainingAudio').onclick=stopAudio;target().querySelector('#readTrainingModel').onclick=()=>{if(busy)return;stopAudio();readingFallback=true;audioUsed=false;if(q.mode==='recall')helped=true;showFallback();};
  target().querySelector('#trainingListen').onclick=()=>{if(busy)return;replays++;const done=()=>{if(!readingFallback)audioUsed=true;say('Puoi riascoltare tutte le volte che vuoi.');};isLetter?speakLetter(q.letter.id,'en-GB',done):speakParts([{text:q.mode==='phrase'?q.word.phrase:word}],'en-GB',done);};
  target().querySelector('#trainingItalian')?.addEventListener('click',()=>{if(busy)return;hint(true);speakLetter(q.letter.id,'it-IT');});
  target().querySelector('#trainingHint').onclick=()=>hint();
  if(!isLetter&&['build','recall'].includes(q.mode)){const letters=[...word.toUpperCase()];const sequence=document.createElement('button');sequence.className='audio';sequence.id='trainingSpellListen';sequence.textContent='🔊 Ascolta i nomi delle lettere';sequence.disabled=!letters.every(verified);sequence.onclick=()=>{if(busy)return;hint();replays++;speakParts(letters.map(id=>({text:content.letters.find(l=>l.id===id).en,letter:id})),'en-GB');};target().querySelector('.trainingAudio').append(sequence);if(sequence.disabled){const note=document.createElement('p');note.className='hint';note.textContent='I nomi inglesi delle singole lettere si ascoltano dopo il controllo con un adulto nell’alfabeto. Puoi intanto ascoltare la parola intera.';sequence.after(note);}}
  if(session.hint)renderHint(session.hint);updateAudioControls();root.querySelector('h2').focus({preventScroll:true});root.scrollIntoView({block:'start'});
 }
 function build(word,host){const letters=[...word].map((char,id)=>({char,id}));for(let i=letters.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[letters[i],letters[j]]=[letters[j],letters[i]];}const picked=[];
  host.innerHTML='<div class="trainingSlots" role="group" aria-label="La parola composta"></div><div class="trainingTiles" role="group" aria-label="Lettere disponibili">'+letters.map(t=>'<button class="audio" data-training-tile="'+t.id+'" aria-label="Lettera '+esc(t.char.toUpperCase())+', tessera '+t.id+'">'+esc(t.char)+'</button>').join('')+'</div><p id="trainingBuildCount" role="status"></p><button class="primary" id="trainingBuildCheck">Controlla</button>';
  function update(){host.querySelector('.trainingSlots').innerHTML=picked.map((t,i)=>'<button class="audio" data-training-slot="'+i+'" aria-label="Togli la lettera '+esc(t.char)+'">'+esc(t.char)+'</button>').join('');host.querySelectorAll('[data-training-tile]').forEach(b=>b.disabled=picked.some(t=>t.id===Number(b.dataset.trainingTile)));host.querySelectorAll('[data-training-slot]').forEach(b=>b.onclick=()=>{if(busy)return;const removed=picked.splice(Number(b.dataset.trainingSlot),1)[0];update();host.querySelector('[data-training-tile="'+removed.id+'"]').focus();});host.querySelector('#trainingBuildCount').textContent=picked.length+' di '+letters.length+' lettere';}
  host.querySelectorAll('[data-training-tile]').forEach(b=>b.onclick=()=>{if(busy||picked.some(t=>t.id===Number(b.dataset.trainingTile)))return;picked.push(letters.find(t=>t.id===Number(b.dataset.trainingTile)));update();(host.querySelector('[data-training-tile]:not(:disabled)')||host.querySelector('#trainingBuildCheck')).focus();});host.querySelector('#trainingBuildCheck').onclick=()=>answer(picked.map(t=>t.char).join(''));update();
 }
